arguments.command:
python3 << 'EOF'
import parse

@parse.with_pattern(r'\w+')
def word_convert(s):
    return s.upper()

extra_types = {'word': word_convert}

p = parse.Parser('{word}', extra_types=extra_types)
print('Expression:', p._expression)

result = list(parse.findall('{word}', 'Hello world hello WORLD', extra_types=extra_types))
print('Matches:', [r.named['word'] for r in result])
EOF
